var PROVIDER_SETTINGS_CSS = `
.bt-provider-settings{gap:20px}
.bt-provider-section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:0 4px}
.bt-provider-section-head>h3{margin:0;font-size:13px;line-height:18px;font-weight:600}
.bt-provider{border-top:.5px solid var(--bt-line)}
.bt-provider:first-of-type{border-top:0}
.bt-provider-summary{width:100%}
.bt-provider-title{display:flex;align-items:center;gap:8px;min-width:0;font-weight:500}
.bt-provider-id{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11px;color:var(--bt-ink-3);overflow:hidden;text-overflow:ellipsis}
.bt-provider .bt-set-hint[data-error]{color:var(--bt-danger)}
.bt-provider-state{display:inline-flex;align-items:center;gap:6px;font-size:12px;line-height:16px;color:var(--bt-ink-2);white-space:nowrap}
.bt-provider-state::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--bt-ink-3)}
.bt-provider-state[data-state=set]::before{background:var(--bt-green)}
.bt-provider-state[data-state=missing]{color:var(--bt-danger)}
.bt-provider-state[data-state=missing]::before{background:var(--bt-danger)}
.bt-provider-edit{padding:0 16px 14px;display:flex;flex-direction:column;gap:12px;background:color-mix(in srgb,var(--bt-hover) 35%,transparent)}
.bt-provider-roles{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}
.bt-provider-role{padding:1px 7px;border-radius:999px;background:var(--bt-tag-bg);color:var(--bt-tag-ink);font-size:11px;line-height:18px}
.bt-provider-key-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.bt-provider-key-row .bt-secret-field{flex:1 1 260px;min-width:0;display:flex;align-items:center;gap:8px;min-height:32px;padding:0 10px;border:.5px solid var(--bt-line-2);border-radius:var(--bt-radius-input);background:var(--bt-card)}
.bt-provider-key-row .bt-secret-input{border:0;padding:0;background:none}
.bt-provider-ok{display:flex;align-items:center;gap:6px;color:var(--bt-green)}
.bt-provider-models{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.bt-provider-models .bt-tag{max-width:220px}
.bt-provider-models-head{display:flex;align-items:center;justify-content:space-between;gap:8px}
.bt-provider-add{display:flex;flex-direction:column;gap:12px;padding:14px 16px;border-top:.5px solid var(--bt-line);background:color-mix(in srgb,var(--bt-hover) 35%,transparent);animation:bt-page-up ${SPRING_SHAPE.duration}ms ${SPRING_SHAPE.easing} backwards}
.bt-provider-add>.bt-seg{align-self:flex-start}
.bt-provider-add .bt-seg button{flex:none;padding:0 14px;white-space:nowrap}
.bt-provider-form{display:flex;flex-direction:column;gap:10px}
.bt-provider-form .bt-secret-field{min-height:34px;display:flex;align-items:center;gap:8px;padding:0 10px;border:.5px solid var(--bt-line-2);border-radius:var(--bt-radius-input);background:var(--bt-card)}
.bt-provider-form .bt-secret-input{border:0;padding:0;background:none}
.bt-provider-form .bt-secret-field>svg{flex:none;color:var(--bt-ink-3)}
.bt-provider-pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.bt-provider-pair .bt-input,.bt-provider-pair .bt-select{min-width:0;width:100%}
.bt-provider-missing{color:var(--bt-danger)}
.bt-provider-draft{display:flex;flex-direction:column;gap:8px}
.bt-provider-draft-group{display:flex;flex-direction:column;gap:6px}
.bt-provider-found{display:flex;flex-wrap:wrap;gap:6px;max-height:180px;overflow-y:auto;scrollbar-width:thin;padding:3px;margin:-3px}
.bt-provider-model-choice{display:inline-flex;align-items:center;gap:6px;min-height:28px;padding:2px 8px;border:.5px solid var(--bt-line-2);border-radius:var(--bt-radius-pill);background:var(--bt-card);color:var(--bt-ink-2);font:inherit;cursor:pointer}
.bt-provider-model-choice[aria-pressed=true]{border-color:var(--bt-accent);color:var(--bt-ink);background:color-mix(in srgb,var(--bt-accent) 8%,var(--bt-card))}
.bt-provider-model-choice code{font:11px/16px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.bt-provider-model-choice svg{width:13px;height:13px;color:var(--bt-accent)}
.bt-provider-actions{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:8px}
.bt-provider-actions .bt-set-hint{margin-right:auto}
@media(max-width:560px){.bt-provider-pair{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.bt-provider-add{animation:none}}
`;

